using BrewNest.Modules.Procurement.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BrewNest.Modules.Procurement.Infrastructure.EntityConfigurations;
internal static class ConfigurationHelpers { public static void Document<T>(EntityTypeBuilder<T> b,string table) where T:ProcurementDocument { b.ToTable(table);b.HasKey(x=>x.Id);b.Property(x=>x.Number).HasMaxLength(40).IsRequired();b.HasIndex(x=>x.Number).IsUnique();b.Property(x=>x.CreatedBy).HasMaxLength(200);b.Property(x=>x.ModifiedBy).HasMaxLength(200);b.Property(x=>x.RowVersion).IsRowVersion(); } public static void Money(PropertyBuilder<decimal> p)=>p.HasPrecision(18,2);public static void Quantity(PropertyBuilder<decimal> p)=>p.HasPrecision(18,3); }
internal sealed class PrConfiguration:IEntityTypeConfiguration<PurchaseRequisition>{public void Configure(EntityTypeBuilder<PurchaseRequisition>b){ConfigurationHelpers.Document(b,"PurchaseRequisitions");b.Property(x=>x.Department).HasMaxLength(100);b.Property(x=>x.Reason).HasMaxLength(500);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasMany(x=>x.Lines).WithOne(x=>x.Requisition).HasForeignKey(x=>x.RequisitionId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PrLineConfiguration:IEntityTypeConfiguration<PurchaseRequisitionLine>{public void Configure(EntityTypeBuilder<PurchaseRequisitionLine>b){b.ToTable("PurchaseRequisitionLines");b.HasKey(x=>x.Id);ConfigurationHelpers.Quantity(b.Property(x=>x.Quantity));ConfigurationHelpers.Money(b.Property(x=>x.EstimatedUnitPrice));b.Property(x=>x.Notes).HasMaxLength(500);}}
internal sealed class RfqConfiguration:IEntityTypeConfiguration<RequestForQuotation>{public void Configure(EntityTypeBuilder<RequestForQuotation>b){ConfigurationHelpers.Document(b,"RequestsForQuotation");b.Property(x=>x.Status).HasMaxLength(30);b.HasMany(x=>x.Vendors).WithOne(x=>x.Rfq).HasForeignKey(x=>x.RfqId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Quotations).WithOne(x=>x.Rfq).HasForeignKey(x=>x.RfqId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class RfqVendorConfiguration:IEntityTypeConfiguration<RfqVendor>{public void Configure(EntityTypeBuilder<RfqVendor>b){b.ToTable("RfqVendors");b.HasKey(x=>x.Id);b.HasIndex(x=>new{x.RfqId,x.VendorId}).IsUnique();}}
internal sealed class QuotationConfiguration:IEntityTypeConfiguration<VendorQuotation>{public void Configure(EntityTypeBuilder<VendorQuotation>b){ConfigurationHelpers.Document(b,"VendorQuotations");b.Property(x=>x.VendorName).HasMaxLength(200);b.Property(x=>x.Reference).HasMaxLength(100);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasMany(x=>x.Lines).WithOne(x=>x.Quotation).HasForeignKey(x=>x.QuotationId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class QuotationLineConfiguration:IEntityTypeConfiguration<VendorQuotationLine>{public void Configure(EntityTypeBuilder<VendorQuotationLine>b){b.ToTable("VendorQuotationLines");b.HasKey(x=>x.Id);ConfigurationHelpers.Quantity(b.Property(x=>x.Quantity));ConfigurationHelpers.Money(b.Property(x=>x.UnitPrice));}}
internal sealed class PoConfiguration:IEntityTypeConfiguration<PurchaseOrder>{public void Configure(EntityTypeBuilder<PurchaseOrder>b){ConfigurationHelpers.Document(b,"PurchaseOrders");b.Property(x=>x.VendorName).HasMaxLength(200);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasMany(x=>x.Lines).WithOne(x=>x.PurchaseOrder).HasForeignKey(x=>x.PurchaseOrderId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Approvals).WithOne(x=>x.PurchaseOrder).HasForeignKey(x=>x.PurchaseOrderId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PoLineConfiguration:IEntityTypeConfiguration<PurchaseOrderLine>{public void Configure(EntityTypeBuilder<PurchaseOrderLine>b){b.ToTable("PurchaseOrderLines");b.HasKey(x=>x.Id);ConfigurationHelpers.Quantity(b.Property(x=>x.Quantity));ConfigurationHelpers.Quantity(b.Property(x=>x.ReceivedQuantity));ConfigurationHelpers.Money(b.Property(x=>x.UnitPrice));}}
internal sealed class ApprovalConfiguration:IEntityTypeConfiguration<ProcurementApprovalDecision>{public void Configure(EntityTypeBuilder<ProcurementApprovalDecision>b){b.ToTable("ApprovalDecisions");b.HasKey(x=>x.Id);b.Property(x=>x.RequiredRole).HasMaxLength(100);b.Property(x=>x.Decision).HasMaxLength(30);b.Property(x=>x.DecidedBy).HasMaxLength(200);b.Property(x=>x.Remarks).HasMaxLength(500);}}
internal sealed class ReceiptConfiguration:IEntityTypeConfiguration<GoodsReceipt>{public void Configure(EntityTypeBuilder<GoodsReceipt>b){ConfigurationHelpers.Document(b,"GoodsReceipts");b.Property(x=>x.SupplierReference).HasMaxLength(100);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasMany(x=>x.Lines).WithOne(x=>x.GoodsReceipt).HasForeignKey(x=>x.GoodsReceiptId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ReceiptLineConfiguration:IEntityTypeConfiguration<GoodsReceiptLine>{public void Configure(EntityTypeBuilder<GoodsReceiptLine>b){b.ToTable("GoodsReceiptLines");b.HasKey(x=>x.Id);b.Property(x=>x.LotNumber).HasMaxLength(100);b.Property(x=>x.Inspection).HasConversion<string>().HasMaxLength(30);ConfigurationHelpers.Quantity(b.Property(x=>x.Quantity));b.HasMany(x=>x.InspectionResults).WithOne(x=>x.GoodsReceiptLine).HasForeignKey(x=>x.GoodsReceiptLineId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class InspectionConfiguration:IEntityTypeConfiguration<QualityInspectionResult>{public void Configure(EntityTypeBuilder<QualityInspectionResult>b){b.ToTable("QualityInspectionResults");b.HasKey(x=>x.Id);b.Property(x=>x.Criterion).HasMaxLength(200);b.Property(x=>x.Result).HasMaxLength(500);b.Property(x=>x.Remarks).HasMaxLength(500);b.Property(x=>x.SupportingReference).HasMaxLength(500);b.Property(x=>x.Inspector).HasMaxLength(200);}}
internal sealed class ReturnConfiguration:IEntityTypeConfiguration<VendorReturn>{public void Configure(EntityTypeBuilder<VendorReturn>b){ConfigurationHelpers.Document(b,"VendorReturns");b.Property(x=>x.Reason).HasMaxLength(500);b.HasMany(x=>x.Lines).WithOne(x=>x.VendorReturn).HasForeignKey(x=>x.VendorReturnId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ReturnLineConfiguration:IEntityTypeConfiguration<VendorReturnLine>{public void Configure(EntityTypeBuilder<VendorReturnLine>b){b.ToTable("VendorReturnLines");b.HasKey(x=>x.Id);ConfigurationHelpers.Quantity(b.Property(x=>x.Quantity));}}
internal sealed class HistoryConfiguration:IEntityTypeConfiguration<ProcurementStatusHistory>{public void Configure(EntityTypeBuilder<ProcurementStatusHistory>b){b.ToTable("StatusHistory");b.HasKey(x=>x.Id);b.Property(x=>x.DocumentType).HasMaxLength(50);b.Property(x=>x.PreviousStatus).HasMaxLength(30);b.Property(x=>x.NewStatus).HasMaxLength(30);b.Property(x=>x.Reason).HasMaxLength(500);b.Property(x=>x.ChangedBy).HasMaxLength(200);}}
